181. fn sync_port(platform: &Platform, state: &DbConnector, phys: usize, port: &str) -> Result<(), Box<dyn Error>> {
182.     let sfp = platform.sfp(phys)?;
183.     let info_key = format!("{INFO_TABLE}|{port}");
184.     let sw_key = format!("{STATUS_SW_TABLE}|{port}");
185.     let dom_key = format!("{DOM_SENSOR_TABLE}|{port}");
186.     let threshold_key = format!("{DOM_THRESHOLD_TABLE}|{port}");
187. 
188.     if sfp.get_presence()? {
189.         // A present / (re-)inserted module is INSERTED and clears any prior error
190.         // (matches the golden STATUS_SW and recovers a port out of a blocking-error
191.         // state). Do this first so status='1' is visible even if the EEPROM isn't
192.         // ready to read the identity yet (mirrors the Python insert branch, which
193.         // sets SFP_STATUS_INSERTED before post_port_sfp_info_to_db).
194.         state.hset(&sw_key, "status", &CxxString::from("1"))?;
195.         state.hset(&sw_key, "cmis_state", &CxxString::from("READY"))?;
196.         state.hset(&sw_key, "error", &CxxString::from("N/A"))?;
197. 
198.         // get_transceiver_info() returns None (-> JSON null) while the EEPROM is not
199.         // ready yet — most commonly right after a hot re-insert (upstream cmis.py
200.         // returns None if *any* field read yields None). Leave TRANSCEIVER_INFO
201.         // unpopulated so `reconcile_info` retries it, mirroring the reference
202.         // SFP_EEPROM_NOT_READY -> retry_eeprom_reading path (xcvrd.py:558-566).
203.         let info = sfp.get_transceiver_info()?;
204.         let obj = match info.as_object() {
205.             Some(o) => o,
206.             None => return Ok(()),
207.         };
208.         let is_cmis = obj.contains_key("cmis_rev");
209.         for (field, value) in obj {
210.             // active_apsel_hostlaneN is NOT owned by the identity publish: the CMIS
211.             // manager's post_port_active_apsel_to_db writes 'N/A' for every host lane
212.             // that is masked out / until the datapath activates
213.             // (cmis/cmis_manager_task.py:751-770). Don't leak the raw numeric
214.             // get_active_apsel_hostlane() value straight from get_transceiver_info().
215.             if field.starts_with("active_apsel_hostlane") {
216.                 continue;
217.             }
218.             if let Some(s) = stringify_field(value) {
219.                 state.hset(&info_key, field, &CxxString::from(s.as_str()))?;
220.             }
221.         }
222.         let replaceable = sfp.is_replaceable().unwrap_or(false);
223.         state.hset(&info_key, "is_replaceable", &CxxString::from(pybool(replaceable)))?;
224.         // Active ApSel projection (post_port_active_apsel_to_db): with no active
225.         // datapath the host_lanes_mask is 0, so every host lane is 'N/A' (this is
226.         // exactly what the golden pins for the emulated 40G-LR4). CMIS modules only.
227.         if is_cmis {
228.             for lane in 1..=CMIS_MAX_HOST_LANES {
229.                 state.hset(&info_key, &format!("active_apsel_hostlane{lane}"), &CxxString::from("N/A"))?;
230.             }
231.         }
232.         // DOM thresholds are static-per-module; publish them on (re-)insert. Read
233.         // through the pyo3 stringifying reader (the JSON bridge can't marshal the
234.         // -inf power thresholds this module reports); an empty read (feature
235.         // absent) is treated as "not available" so it never blocks identity.
236.         let thresholds = crate::hal::read_thresholds_stringified(phys);
237.         let _ = write_dom_row(&thresholds, state, &threshold_key);
238.     } else {
239.         state.del(&info_key)?;
240.         state.del(&dom_key)?;
241.         state.del(&threshold_key)?;
242.         state.hset(&sw_key, "status", &CxxString::from("0"))?;
243.         state.hset(&sw_key, "error", &CxxString::from("N/A"))?;
244.     }
245.     Ok(())

