22. pub enum CmisState {
23.     Unknown,
24.     Inserted,
25.     DpPreInitCheck,
26.     DpDeinit,
27.     ApConfigured,
28.     DpActivation,
29.     DpInit,
30.     DpTxOn,
31.     Ready,
32.     Removed,
33.     Failed,
