36. impl CmisState {
37.     pub fn as_str(&self) -> &'static str {
38.         match self {
39.             CmisState::Unknown => "UNKNOWN",
40.             CmisState::Inserted => "INSERTED",
41.             CmisState::DpPreInitCheck => "DP_PRE_INIT_CHECK",
42.             CmisState::DpDeinit => "DP_DEINIT",
43.             CmisState::ApConfigured => "AP_CONFIGURED",
44.             CmisState::DpActivation => "DP_ACTIVATION",
45.             CmisState::DpInit => "DP_INIT",
46.             CmisState::DpTxOn => "DP_TXON",
47.             CmisState::Ready => "READY",
48.             CmisState::Removed => "REMOVED",
49.             CmisState::Failed => "FAILED",
50.         }
51.     }
52. 
53.     /// Parse a STATE_DB `cmis_state` string back into the enum (`UNKNOWN` fallback).
54.     pub fn from_str(s: &str) -> CmisState {
55.         match s {
56.             "INSERTED" => CmisState::Inserted,
57.             "DP_PRE_INIT_CHECK" => CmisState::DpPreInitCheck,
58.             "DP_DEINIT" => CmisState::DpDeinit,
59.             "AP_CONFIGURED" => CmisState::ApConfigured,
60.             "DP_ACTIVATION" => CmisState::DpActivation,
61.             "DP_INIT" => CmisState::DpInit,
62.             "DP_TXON" => CmisState::DpTxOn,
63.             "READY" => CmisState::Ready,
64.             "REMOVED" => CmisState::Removed,
65.             "FAILED" => CmisState::Failed,
66.             _ => CmisState::Unknown,
67.         }
68.     }
