70.     /// `CMIS_TERMINAL_STATES` = {FAILED, READY, REMOVED}.
71.     pub fn is_terminal(&self) -> bool {
72.         matches!(self, CmisState::Failed | CmisState::Ready | CmisState::Removed)
73.     }
74. }
