124. /// `_wrapper_is_flat_memory` (`common.py:300`): flat-memory (SFF) module?
125. /// `Some(true)` flat, `Some(false)` paged, `Some(true)` when there is no xcvr api
126. /// (Python `if not api: return True`), `None` on `NotImplementedError`.
127. pub fn wrapper_is_flat_memory<S: SfpApi>(sfp: &S) -> Option<bool> {
128.     match sfp.is_flat_memory() {
129.         Ok(Some(b)) => Some(b),
130.         Ok(None) => Some(true), // no xcvr api -> flat
131.         Err(_) => None,         // NotImplementedError -> None
132.     }
133. }
