135. /// Python-style bool rendering, matching `str(bool)` the reference daemon writes.
136. pub fn pybool(b: bool) -> &'static str {
137.     if b {
138.         "True"
139.     } else {
140.         "False"
141.     }
142. }
143. 
144. /// Render a HAL identity/DOM/etc. field as the STATE_DB string the reference
145. /// daemon writes (`str(value)`), stripping NUL padding on CMIS strings.
146. ///
147. /// Faithfulness rules pinned by the M6 golden projection:
148. /// - **Strings**: NUL padding removed (CMIS fields are fixed-width, NUL-padded;
149. ///   the e2e harness strips NULs on read). Trailing SPACES are kept — e.g.
150. ///   `vendor_date` "2024-12-14 " keeps its trailing space.
151. /// - **bool** -> `True`/`False`; **number** -> canonical (`100.0`, `4`).
152. /// - **dict/list** (e.g. `application_advertisement`) -> Python `repr`, not JSON,
153. ///   because the reference does `str(value)` on the original Python object
154. ///   (`{1: {'host_...': 'XLAUI...', ...}}`).
155. /// - **null** -> field skipped (the golden module emits no null identity fields).
156. pub fn stringify_field(value: &serde_json::Value) -> Option<String> {
157.     use serde_json::Value;
158.     match value {
159.         Value::Null => None,
160.         Value::String(s) => Some(strip_nuls(s)),
161.         Value::Bool(b) => Some(pybool(*b).to_string()),
162.         Value::Number(n) => Some(n.to_string()),
163.         other => Some(py_repr(other)),
164.     }
165. }
166. 
167. /// Remove NUL padding from a CMIS string (the e2e harness does the same on read:
168. /// `out.replace("\x00", "")`). Spaces are intentionally preserved.
169. fn strip_nuls(s: &str) -> String {
170.     s.replace('\0', "")
171. }
172. 
173. /// Python `repr()` of a JSON value — used for nested dict/list identity fields so
174. /// the STATE_DB string matches the reference daemon's `str(value)` on the original
175. /// Python object (e.g. `application_advertisement`).
176. fn py_repr(value: &serde_json::Value) -> String {
177.     use serde_json::Value;
178.     match value {
179.         Value::Null => "None".to_string(),
180.         Value::Bool(b) => pybool(*b).to_string(),
181.         Value::Number(n) => n.to_string(),
182.         Value::String(s) => py_str_repr(s),
183.         Value::Array(a) => {
184.             let items: Vec<String> = a.iter().map(py_repr).collect();
185.             format!("[{}]", items.join(", "))
186.         }
187.         Value::Object(o) => {
188.             // preserve_order keeps insertion (CMIS-decode) order — the golden
189.             // application_advertisement pins that exact inner ordering.
190.             let items: Vec<String> = o
191.                 .iter()
192.                 .map(|(k, v)| format!("{}: {}", py_key_repr(k), py_repr(v)))
193.                 .collect();
194.             format!("{{{}}}", items.join(", "))
195.         }
196.     }
197. }
198. 
199. /// Python `repr()` of a string: single-quoted by default, switching to double
200. /// quotes only when the string has a single quote but no double quote (CPython's
201. /// rule), escaping backslashes / the quote char / common control chars.
202. fn py_str_repr(s: &str) -> String {
203.     let s = strip_nuls(s);
204.     let q = if s.contains('\'') && !s.contains('"') { '"' } else { '\'' };
205.     let mut out = String::with_capacity(s.len() + 2);
206.     out.push(q);
207.     for c in s.chars() {
208.         match c {
209.             '\\' => out.push_str("\\\\"),
210.             '\n' => out.push_str("\\n"),
211.             '\r' => out.push_str("\\r"),
212.             '\t' => out.push_str("\\t"),
213.             c if c == q => {
214.                 out.push('\\');
215.                 out.push(c);
216.             }
217.             c => out.push(c),
218.         }
219.     }
220.     out.push(q);
221.     out
222. }
223. 
224. /// Python `repr()` of a dict key. `json.dumps` stringifies non-string keys, so a
225. /// key that round-trips through `i64` (e.g. the `application_advertisement`
226. /// app-selector `1`) was an int in Python and is rendered unquoted; anything else
227. /// is a quoted string.
228. fn py_key_repr(k: &str) -> String {
229.     if k.parse::<i64>().map(|n| n.to_string() == *k).unwrap_or(false) {
230.         k.to_string()
231.     } else {
232.         py_str_repr(k)
233.     }
234. }
235. 
236. /// Convert a HAL dict `Value` into a STATE_DB `Row` (field -> stringified value).
237. pub fn value_to_row(value: &serde_json::Value) -> Row {
238.     let mut row = Row::new();
239.     if let Some(obj) = value.as_object() {
240.         for (field, v) in obj {
241.             if let Some(s) = stringify_field(v) {
242.                 row.insert(field.clone(), s);
243.             }
244.         }
245.     }
246.     row
247. }
